package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamWesternClassicBank4 {
    private const val T = "බටහිර සම්භාව්‍ය කලාව (මිසර, ග්‍රීක, රෝම, පුනරුද, බැරොක්)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උතුරු පුනරුදයේ නෙදර්ලන්ත ශිල්පී 'ජෑන් වැන් අයික්' (Jan van Eyck) 1434 දී ඇඳි 'ආර්නොල්ෆිනි යුවළ' සිතුවම ප්‍රසිද්ධ වන්නේ කුමක් නිසාද?", "තෙල් සායම් සියුම් විස්තර හා පිටුපස උත්තල කැඩපත", "අධික ඝන පිහි පහරවල් හා වියුක්ත රේඛා නිසා", "කිසිදු වර්ණයක් නැතිව පැන්සලෙන් ඇඳ තිබීම නිසා", "ග්‍රීක දෙවිවරුන්ගේ මූර්ති පිටපත් කර තිබීම නිසා", "තුනී තෙල් සායම් ස්තර (Glazes) මගින් ලෝහ, රෙදි හා කැඩපතේ පරාවර්තනය අතිශය සියුම්ව නිරූපණය කළේය."),
        q("ලන්ඩන් ජාතික කලාගාරයේ ඇති හෑන්ස් හොල්බයින් (Hans Holbein) ඇඳි 'තානාපතිවරු' (The Ambassadors) සිතුවමේ පහළ ඇති අමුතු හැඩය කුමක්ද?", "ඇල කෝණයෙන් බලන විට පෙනෙන මිනිස් හිස්කබලකි", "අභ්‍යවකාශ යානයක තාක්ෂණික සැලැස්මකි", "සිංහල හංස පූට්ටුවක ජ්‍යාමිතික රටාවකි", "රෝමානු පැන්තියන් ගෝලයේ හරස්කඩ සිතියමකි", "ඇනමෝෆික් දෘෂ්ටිකෝණයෙන් (Anamorphic Perspective) ඇඳි හිස්කබල ලෞකික දැනුමේ අනිත්‍යතාව සිහිගන්වයි."),
        q("මුල් නෙදර්ලන්ත ශිල්පී හයිරොනිමස් බොෂ් (Hieronymus Bosch) ගේ 'ලෞකික සැප සම්පත් උයන' සිතුවමේ ප්‍රධාන ලක්ෂණය කුමක්ද?", "අද්භූත කල්පිත සතුන් හා සංකේතාත්මක පණිවිඩ", "ගොවි ජනතාවගේ සරල මැටි නිවාස සිතුවම්", "ශාන්ත මරියතුමියගේ සාමකාමී හිඳි ආලේඛ්‍ය", "මධ්‍යධරණී මුහුදු යාත්‍රාවල යථාර්ථවාදී දසුන්", "ත්‍රිත්ව පුවරු (Triptych) ආකෘතියේ ඇඳි මෙය පසුකාලීන 20 වන සියවසේ සර්රියලිස්ට්වාදීන්ටද බලපෑවේය."),
        q("පුනරුද යුගයේ 'වැනීසියානු ශෛලියෙන්' සිතුවම් ඇඳි ටින්ටොරෙටෝ (Tintoretto) ගේ 'අවසන් රාත්‍රී භෝජනය' ඩා වින්චිගෙන් වෙනස් වන්නේ කෙසේද?", "ගැඹුරු විකර්ණ මේසය හා අද්භූත අඳුරු ආලෝකයයි", "සමමිතික තිරස් මේසය හා සුදුමැලි දිවා ආලෝකයයි", "මේසයක් නොමැතිව එළිමහන් කඳු මුදුනක ඇඳීමයි", "වර්ණ චක්‍රයේ කොළ හා කහ පමණක් භාවිත කිරීමයි", "ඩා වින්චිගේ සංයමී සමමිතිය වෙනුවට ටින්ටොරෙටෝ මැනරිස්ට්-බැරොක් නාට්‍යමය චලනයක් හා දේවදූතයන් එක් කළේය."),
        q("ඉතාලියේ විසෙන්සා නුවර 'විලා රොටොන්ඩා' (Villa Rotonda) නිර්මාණය කර බටහිර වාස්තු කලාවට බලපෑම් කළ පුනරුද ගෘහ නිර්මාණ ශිල්පියා කවුද?", "ඇන්ඩ්‍රියා පැලෑඩියෝ (Andrea Palladio)", "ජොහැන්නස් වර්මියර් (Johannes Vermeer)", "පීටර් බෲගල් (Pieter Bruegel)", "ජැක් ලුවී ඩේවිඩ් (Jacques-Louis David)", "සතර දිසාවේම ග්‍රීක පෝටිකෝ ඇති පරිපූර්ණ සමමිතික ගොඩනැගිලි රීතිය පසුව ඇමරිකාව හා යුරෝපය පුරා පැතිරිණි."),
        q("බැරොක් යුගයේ ඉතාලියේ කාන්තා චිත්‍ර ශිල්පිනියක ලෙස කැරවැජියෝ ආභාසයෙන් ප්‍රබල කෘති බිහි කළ ශිල්පිනිය කවුද?", "ආටිමීසියා ජෙන්ටිලෙස්කි (Artemisia Gentileschi)", "මේරි කැසැට් (Mary Cassatt)", "ෆ්‍රීඩා කාලෝ (Frida Kahlo)", "ජෝර්ජියා ඕකීෆ් (Georgia O'Keeffe)", "තීව්‍ර චියරොස්කුරෝ ආලෝකය යොදා ධෛර්යසම්පන්න කාන්තා චරිත ඇඳි ඇය බැරොක් යුගයේ පුරෝගාමී ශිල්පිනියකි."),
        q("18 වන සියවසේ ප්‍රංශයේ බිහි වූ 'රොකෝකෝ' (Rococo) කලා ව්‍යාපාරය බැරොක් කලාවෙන් වෙනස් වන්නේ කුමන ගුණයෙන්ද?", "සැහැල්ලු පැස්ටල් වර්ණ, වක්‍ර රේඛා හා ප්‍රීතිමත් තේමා", "තද අඳුරු සෙවණැලි හා බරපතල ආගමික ශෝකය", "සෘජුකෝණාස්‍රාකාර සමමිතික යුද ජයග්‍රහණ පමණි", "රළු ගල් කුට්ටි මත කෙටූ අමූර්ත කැටයම්", "ප්‍රංශ වංශවතුන්ගේ විනෝදකාමී ජීවිතය රෝස, ලා නිල් හා රන්වන් වක්‍ර සැරසිලිවලින් රොකෝකෝ කලාව පෙන්වීය."),
        q("රොකෝකෝ කලාවේ වඩාත් ප්‍රසිද්ධ සිතුවමක් වන 'ඔන්චිල්ලාව' (The Swing / 1767) නිර්මාණය කළ ප්‍රංශ චිත්‍ර ශිල්පියා කවුද?", "ජීන්-හොනොරේ ෆ්‍රැගොනාර්ඩ් (Fragonard)", "ජැක් ලුවී ඩේවිඩ් (Jacques-Louis David)", "රෙම්බ්‍රාන්ට් වැන් රේන් (Rembrandt)", "මයිකල්ඇන්ජලෝ බුවනරෝති (Michelangelo)", "සරල උද්‍යාන වනගොමුවක් තුළ පාවෙන රෝස ඇඳුමින් සැරසුණු යුවතිය රොකෝකෝ සැහැල්ලු රසයේ සංකේතයයි."),
        q("රොකෝකෝ යුගයේ 'ෆේට් ගැලන්ටේ' (Fete Galante - එළිමහන් ප්‍රේමණීය උත්සව) සිතුවම් කලාවේ පුරෝගාමියා කවුද?", "ඇන්ටොයින් වටෝ (Antoine Watteau)", "ෆ්‍රැන්සිස්කෝ ගෝයා (Francisco Goya)", "දොනතෙල්ලෝ (Donatello)", "ජොටෝ ඩි බොන්ඩෝනේ (Giotto)", "සිතේරා දූපතට යන වන්දනාව වැනි කෘතිවලින් ඔහු සියුම් මනෝභාවයන් හා සිහිනමය වර්ණ මැවීය."),
        q("රොකෝකෝ කලාවේ අතිශයෝක්තික විලාසිතාවට එරෙහිව 18 වන සියවස අගදී බිහි වූ නව ව්‍යාපාරය කුමක්ද?", "නව-සම්භාව්‍යවාදය (Neoclassicism)", "ගොතික් වාස්තු කලාව (Gothic Art)", "රොමෑන්තිකවාදය (Romanticism)", "ප්‍රකාශනවාදය (Expressionism)", "පොම්පේයි කැණීම් හා ග්‍රීක-රෝම විනය සිහිගන්වමින් සරල, ඍජු හා දේශප්‍රේමී කලාවක් ලෙස මෙය බිහිවිය."),
        q("නව-සම්භාව්‍යවාදී (Neoclassical) ප්‍රධාන ප්‍රංශ චිත්‍ර ශිල්පී 'ජැක් ලුවී ඩේවිඩ්' ඇඳි කැපී පෙනෙන විප්ලවීය සිතුවම් දෙක මොනවාද?", "හොරේෂි දිවුරුම සහ මරාට්ගේ මරණය", "වීනස්ගේ උපත සහ වසන්ත සමය", "රාත්‍රී මුරසේවය සහ සිසිර නිවාඩුව", "මහා රළ සහ ෆූජි කන්ද", "පැහැදිලි සමෝච්ඡ රේඛා, ස්ථිර ජ්‍යාමිතික රාමු හා යුතුකම පිළිබඳ හැඟීම ඩේවිඩ්ගේ කෘතිවල මූලික වේ."),
        q("ප්‍රංශ නව-සම්භාව්‍යවාදී මූර්ති ශිල්පී 'ඇන්ටෝනියෝ කැනෝවා' (Antonio Canova) කිරිගරුඬින් නෙළූ සුප්‍රකට කෘතිය කුමක්ද?", "කියුපිඩ්ගේ හාදුවෙන් අවදි වන සයිකි", "අගස්ත්‍ය සෘෂිවරයාගේ කළුගල් ප්‍රතිමාව", "රාත්‍රී අහසේ වියුක්ත ලෝහ කුළුණ", "ශිව නටරාජ ගිනි වළලු ප්‍රතිමාව", "සිනිඳු ඔප දැමූ කිරිගරුඬ මතුපිට හා සමමිතික රේඛා කැනෝවාගේ නව-සම්භාව්‍ය විශිෂ්ටත්වය පෙන්වයි."),
        q("නව-සම්භාව්‍යවාදයේදී 'රේඛාව හා ඇඳීම' (Line/Drawing) වර්ණයට වඩා වැදගත් බව ප්‍රකාශ කළ ප්‍රංශ චිත්‍ර ශිල්පියා කවුද?", "ජීන්-ඕගස්ට්-ඩොමිනික් ඉන්ග්‍රෙස් (Ingres)", "ඉයුජින් ඩෙලැක්‍රොයික්ස් (Delacroix)", "කැරවැජියෝ (Caravaggio)", "ක්ලෝඩ් මොනේ (Claude Monet)", "ඩේවිඩ්ගේ ශිෂ්‍ය ඉන්ග්‍රෙස් 'ග්‍රෑන්ඩ් ඔඩලිස්ක්' වැනි කෘතිවල පිරිසිදු රේඛා ලාලිත්‍යය අගය කළේය."),
        q("18 වන සියවසේ ප්‍රංශ රාජ සභාවේ ජනප්‍රියම කාන්තා ආලේඛ්‍ය චිත්‍ර ශිල්පිනිය (මාරි ඇන්ටොයිනෙට්ගේ සිත්තරිය) කවුද?", "එලිසබෙත් විජේ ලෙ බෲන් (Vigee Le Brun)", "බර්තා මොරිසොට් (Berthe Morisot)", "මේරි කැසැට් (Mary Cassatt)", "හෙලේනා ෆෝමන් (Helena Fourment)", "මෘදු පැස්ටල් හා තෙල් සායමින් ස්වාභාවික මාතෘ ආලේඛ්‍ය හා රාජකීය රූප ඉතා දක්ෂ ලෙස ඇය ඇන්දාය."),
        q("18 වන සියවසේ එංගලන්තයේ සමාජ දූෂණ විවේචනය කරමින් උපහාසාත්මක කතා පෙළවල් සිතුවම් හා මුද්‍රණ කළ ශිල්පියා කවුද?", "විලියම් හොගාර්ත් (William Hogarth)", "ජෝර්ජ් කීට් (George Keyt)", "රෆායෙල් (Raphael)", "බර්නිනි (Bernini)", "'විවාහ අලංකාරය' වැනි මාලා කෘති හරහා සමාජ විවේචනය කලාවට ගෙන ඒමට හොගාර්ත් පුරෝගාමී විය."),
        q("ඉංග්‍රීසි ආලේඛ්‍ය හා භූ දර්ශන කලාවේ 18 වන සියවසේ සුප්‍රකට 'නිල් පිරිමි ළමයා' (The Blue Boy) සිතුවම ඇන්දේ කවුද?", "තෝමස් ගේන්ස්බරෝ (Thomas Gainsborough)", "ජෝෂුවා රෙනෝල්ඩ්ස් (Joshua Reynolds)", "වින්සන්ට් වැන් ගෝ (Van Gogh)", "පැබ්ලෝ පිකාසෝ (Pablo Picasso)", "රෙදිපිළිවල සිසිල් නිල් පැහැය හා මෘදු ස්වභාවික පසුබිම ගේන්ස්බරෝගේ විශේෂිත දක්ෂතාවකි."),
        q("19 වන සියවසේ මුල් භාගයේ නව-සම්භාව්‍ය සංයමයට එරෙහිව හැඟීම්, ස්වභාවධර්මයේ බිහිසුණු බව හා පරිකල්පනය පෙන්වූ කලා ව්‍යාපාරය කුමක්ද?", "රොමෑන්තිකවාදය (Romanticism)", "බයිසැන්ටයින් කලාව (Byzantine)", "මිසර සමමිතික කලාව (Egyptian)", "ග්‍රීක ආකේයික් කලාව (Archaic)", "විප්ලව, කුණාටු මුහුද හා ආවේගශීලී වර්ණ මගින් රොමෑන්තිකවාදීහු තර්කයට වඩා හදවත මුල් කළහ."),
        q("රොමෑන්තිකවාදී ප්‍රංශ ශිල්පී තියඩෝර් ජෙරිකෝ (Gericault) ඇඳි සැබෑ නාවික ඛේදවාචකයක් පිළිබඳ විශාල සිතුවම කුමක්ද?", "මෙඩූසාගේ පහුර (The Raft of the Medusa)", "හොරේෂි දිවුරුම (Oath of the Horatii)", "වීනස්ගේ උපත (Birth of Venus)", "ගර්නිකා (Guernica)", "මුහුදු රළ අතර බලාපොරොත්තුව හා මරණය අතර පිරමීඩ සංයුතියකින් ජීවිත සටන මෙහි නිරූපණය කළේය."),
        q("රොමෑන්තිකවාදයේ ප්‍රංශ නායක 'ඉයුජින් ඩෙලැක්‍රොයික්ස්' (Delacroix) 1830 විප්ලවය වෙනුවෙන් ඇඳි සුප්‍රකට සිතුවම කුමක්ද?", "ජනතාව මෙහෙයවන නිදහස (Liberty Leading the People)", "මියගිය ක්‍රිස්තුස් වහන්සේ (Dead Christ)", "ආර්නොල්ෆිනි යුවළ (Arnolfini Portrait)", "ඇතන්ස් පාසල (School of Athens)", "ත්‍රිවර්ණ ප්‍රංශ ධජය අතැතිව ඉදිරියට යන නිදහසේ දේවතාවිය හා වෙඩි දුමාරය රොමෑන්තික වේගය පෙන්වයි."),
        q("ස්පාඤ්ඤ චිත්‍ර ශිල්පී 'ෆ්‍රැන්සිස්කෝ ගෝයා' (Francisco Goya) ඇඳි '1808 මැයි තුන්වන දා' සිතුවමේ ප්‍රධාන තේමාව කුමක්ද?", "යුද්ධයේ කෲරත්වය හා අහිංසක මිනිසුන්ට වෙඩි තැබීම", "රජුගේ සාමකාමී උද්‍යාන විවේක උත්සවය", "ග්‍රීක දෙවිවරුන්ගේ විවාහ මංගල්‍ය පෙරහැර", "මුහුදු වෙරළේ පැවැත්වෙන ඔරු පැදීමේ තරඟය", "සුදු කමිසයක් හැඳ දෑත් ඔසවා සිටින මිනිසා මත වැටෙන ලන්තෑරුම් ආලෝකය යුද විරෝධී කලාවේ මුල් පියවරකි."),
        q("බ්‍රිතාන්‍ය රොමෑන්තික භූ දර්ශන චිත්‍ර ශිල්පී 'ජේ.එම්.ඩබ්. ටර්නර්' (J.M.W. Turner) තම සිතුවම්වල විශේෂයෙන් ග්‍රහණය කළේ කුමක්ද?", "ආලෝකය, වාෂ්ප, කුණාටු සහ හිරු බැස යෑම්", "සියුම් ජ්‍යාමිතික ගොඩනැගිලි මිනුම් රේඛා", "සිනිඳු පැතලි කාටූන් සමෝච්ඡ රූප", "කළුගල් මූර්තිවල නිශ්චල අඳුරු සෙවණැලි", "හැඩතල ආලෝකයේ හා මීදුමේ දියවී යන ආකාරය ඇඳි ටර්නර් පසුව උපස්ථිතිවාදයට මග පෑදීය."),
        q("බ්‍රිතාන්‍ය භූ දර්ශන ශිල්පී 'ජෝන් කොන්ස්ටබල්' (John Constable) ඇඳි 'ද හේ වේන්' (The Hay Wain) සිතුවමින් ප්‍රකාශ වන්නේ කුමක්ද?", "එංගලන්ත ගැමි පරිසරයේ සාමකාමී සුන්දරත්වය", "කාර්මික කර්මාන්තශාලාවල දුම් කුළුණු භීතිය", "රෝම සෙනෙට් සභාවේ දේශපාලන කුමන්ත්‍රණ", "අභ්‍යවකාශයේ වියුක්ත ග්‍රහලෝක රටා", "සැබෑ වලාකුළු නිරීක්ෂණ හා දිය පහරේ දිලිසීම සුදු තීන්ත තිත් මගින් ඔහු ස්වාභාවිකව සිතුවම් කළේය."),
        q("19 වන සියවසේ මැද භාගයේ ප්‍රංශයේ බිහි වූ 'යථාර්ථවාදය' (Realism - උදා: ගුස්තාව් කූර්බේ) මගින් සිදු කළ වෙනස කුමක්ද?", "සාමාන්‍ය කම්කරුවන් හා දෛනික සැබෑ ජීවිතය ඇඳීම", "දේවදූතයන් හා මිථ්‍යා රජවරුන් පමණක් ඇඳීම", "හීන ලෝකවල පියාපත් ඇති රූප ඇඳීම", "මිසර පාරාවෝ රීතිය නැවත පණ ගැන්වීම", "'මට දේවදූතයෙකු පෙන්වුවහොත් මම ඔහු අඳින්නෙමි' යැයි කී කූර්බේ 'ගල් කඩන්නෝ' වැනි සැබෑ කෘති ඇන්දේය."),
        q("ප්‍රංශ යථාර්ථවාදී චිත්‍ර ශිල්පී ජීන්-ෆ්‍රැන්සුවා මිලේ (Millet) ගේ 'අස්වනු අහුලන්නියෝ' (The Gleaners) සිතුවම අගය කරන්නේ ඇයි?", "දුප්පත් ගොවි කාන්තාවන්ගේ ශ්‍රමයට ගෞරවය දීම නිසා", "රාජ සභාවේ සුඛෝපභෝගී රන් ආභරණ පෙන්වීම නිසා", "සම්පූර්ණයෙන්ම කළු-සුදු තිත් මුද්‍රණයක් වීම නිසා", "වේගවත් කාර්මික දුම්රියක් සිතුවම් කිරීම නිසා", "බිම වැටුණු ධාන්‍ය කරල් අහුලන කාන්තාවන් තිදෙනාට වීරත්වයක් දීමට මිලේ උණුසුම් සන්ධ්‍යා ආලෝකය යෙදීය."),
        q("රෝමානු හා පුනරුද චිත්‍ර ශිල්පයේදී බිත්ති හෝ ලී පුවරු මත වර්ණ දිලිසීමට 'තෙල් සායම්' වෙනුවට මුලින්ම භාවිත කළ මාධ්‍යය කුමක්ද?", "බිත්තර කහ මදය මිශ්‍ර ටෙම්පරා (Egg Tempera)", "කෘත්‍රිම ඇක්‍රිලික් පොලිමර් තීන්ත", "සිලිකන් මිශ්‍ර ප්ලාස්ටික් ස්ප්‍රේ තීන්ත", "ජලයේ දිය කළ චාකෝල් පැන්සල් කුඩු", "බොටිචෙල්ලි හා ජොටෝ යුගයේ වර්ණක බිත්තර කහ මදය සමඟ අඹරා ඉතා ඉක්මනින් වියළෙන සේ ආලේප කළේය."),
        q("පුරාණ ග්‍රීක 'කළු රූප' (Black-Figure) සහ 'රතු රූප' (Red-Figure) මැටි බඳුන් අතර පසුකාලීනව වඩා සියුම් විස්තර දිය හැකි වූයේ කුමකින්ද?", "රතු රූප ක්‍රමයෙනි (පින්සලෙන් රේඛා ඇඳීම නිසා)", "කළු රූප ක්‍රමයෙනි (ඉඳිකටුවෙන් සීරීම නිසා)", "සුදු කාඩ්බෝඩ් ක්‍රමයෙනි (මැලියම් ගෑම නිසා)", "කොළ ග්ලේස් ක්‍රමයෙනි (වීදුරු දිය කිරීම නිසා)", "පසුබිම කළු කර රතු මැටි රූප ඉතිරි කළ රතු-රූප ක්‍රමයේදී පින්සලෙන් මාංශ පේශි සියුම්ව ඇඳිය හැකි විය."),
        q("පුරාණ ග්‍රීක 'ඩෝරික්' කුළුණු සහ 'කොරින්තියන්' කුළුණු මුදුන් (Capitals) හඳුනා ගන්නේ කෙසේද?", "ඩෝරික් සරල පැතලි අතර කොරින්තියන් ඇකැන්තස් පත්‍ර ඇත", "ඩෝරික් කුළුණේ කැරලි ඇති අතර කොරින්තියන් හිස්ය", "ඩෝරික් ලීයෙන් තැනූ අතර කොරින්තියන් යකඩ වේ", "දෙකෙහිම කුළුණු මුදුනේ ගව හිස් කැටයම් පවතී", "ඇකැන්තස් කොළ කැටයමින් පිරුණු විසිතුරු කොරින්තියන් කුළුණු රෝමානු ගෘහ නිර්මාණයේදීද බහුලව භාවිත විය."),
        q("මිසර කලාවේ පාරාවෝ රජෙකුගේ 'කා' (Ka) හෙවත් ආත්මය සදාකාලිකව වාසය කිරීම සඳහා නෙළන ලද ප්‍රතිමාවල ප්‍රධාන ලක්ෂණය කුමක්ද?", "නොබිඳෙන ශක්තිමත් ගල් කුට්ටි සමමිතිය", "ඉතා තුනී ඇද වැටෙනසුලු මැටි කෝටු හැඩය", "නිතර වෙනස් වන තාවකාලික වැලි ආකෘතිය", "සිදුරු හා හිඩැස් බහුල සැහැල්ලු ව්‍යුහය", "අතපය කැඩී යාම වැළැක්වීමට ගල් පසුබිමට තදින් බැඳ කෙළින් ඉදිරිය බලා සිටින සේ නෙළා ඇත."),
        q("රෝමයේ කැරකැල්ලා ස්නානාගාරය හා බැසිලිකා වැනි විශාල ගොඩනැගිලි තැනීමට රෝමානුවන් සොයාගත් විප්ලවීය ගොඩනැගිලි ද්‍රව්‍යය කුමක්ද?", "රෝමානු කොන්ක්‍රීට් (Pozzolana Concrete)", "කපු පුළුන් මිශ්‍ර පේපර් මැෂේ පල්පය", "මල නොබැඳෙන යකඩ හා වීදුරු තහඩු", "හල්මිල්ල දැව හා පොල් අතු වහලය", "ආරුක්කු හා කොන්ක්‍රීට් එක්වීමෙන් ග්‍රීකයන්ට වඩා විශාල අභ්‍යන්තර අවකාශ (Vaults, Domes) රෝමය ගොඩනැඟීය."),
        q("පුනරුද යුගයේ 'වැනීසියානු ශිල්පීන්' ලී පුවරු වෙනුවට 'කැන්වස් රෙදි' (Canvas) භාවිතයට හුරු වීමට ප්‍රධාන භූගෝලීය හේතුව කුමක්ද?", "මුහුදු තෙතමනයෙන් ලී පුවරු නරක් වීම හා රුවල් රෙදි සුලබ වීම", "එවකට ඉතාලියේ සියලුම වනාන්තර කපා අවසන් වීම", "කැන්වස් රෙදි ජල සායම්වලට පමණක් ගැළපීම", "මයිකල්ඇන්ජලෝ ලී පුවරු තහනම් කර තිබීම", "නාවික නගරයක් වූ වැනීසියේ තෙතමනයට ඔරොත්තු දෙන සැහැල්ලු කැන්වස් මත තෙල් සායම් ඉතා ජනප්‍රිය විය."),
        q("මුල් පුනරුද කලාවේ දොනතෙල්ලෝ (Donatello) තැනූ 'ඩේවිඩ්' ප්‍රතිමාව රෝම යුගයෙන් පසු විශේෂ වන්නේ කුමන ශිල්පීය සන්ධිස්ථානයක් නිසාද?", "වසර දහසකට පසු නිමැවූ පළමු නිදහස් නිරුවත් ලෝකඩ රුවයි", "පළමු වරට ඇක්‍රිලික් ප්ලාස්ටික් වලින් තැනූ ප්‍රතිමාවයි", "පර්වත බිත්තියට ඇලී පවතින අර්ධ උන්නත කැටයමකි", "සැබෑ මිනිස් ප්‍රමාණය මෙන් දස ගුණයක් උස මූර්තියකි", "ගොතික් ආගමික දේවස්ථාන රාමුවෙන් මිදී මිනිස් සිරුරේ සුන්දරත්වය යළි සැමරූ පළමු පුනරුද ලෝකඩ ප්‍රතිමාවයි."),
        q("මිසරයේ 'අමර්ණ යුගයේ' (Amarna Period) අක්නාටන් රජුගේ පාලන සමයේ මූර්ති හා සිතුවම්වල ඇති වූ වෙනස කුමක්ද?", "දැඩි නීති බිඳ දිගු මුහුණු හා මෘදු පවුල් දසුන් ඇඳීම", "මිනිස් රූප ඉවත් කර ජ්‍යාමිතික රේඛා පමණක් ඇඳීම", "රෝම සෙනෙට් සභිකයන් මෙන් රැවුල් මූර්ති තැනීම", "පිරමීඩ තුළ වීදුරු ජනෙල් සවි කිරීම ඇරඹීම", "දහස් ගණන් වසරක් නොවෙනස්ව පැවති මිසර ශෛලිය තාවකාලිකව ලිහිල් වී ස්වාභාවික මානුෂික බවක් මතුවිය."),
        q("පුරාණ ග්‍රීක 'රංග ශාලා' (උදා: එපිඩෝරස් රඟහල) කඳු බෑවුම්වල අර්ධ වෘත්තාකාරව ඉදි කළේ කුමන ප්‍රධාන ගුණය ලබා ගැනීමටද?", "ප්‍රේක්ෂකයන් දහස් ගණනකට ශබ්දය පැහැදිලිව ඇසීමට", "හිරු එළිය ඇතුළට නොවැටී සම්පූර්ණ අඳුර තබා ගැනීමට", "මුහුදු ජලය ගලා ඒමෙන් නැව් සටන් පැවැත්වීමට", "වහලයේ වර්ණ වීදුරු කවුළු ආලෝකය වැටීමට", "කඳු ගැටයේ ස්වභාවික හැඩය භාවිත කළ ග්‍රීක රඟහල්වල ධ්වනි විද්‍යාව (Acoustics) අදටත් විශ්මයජනකය."),
        q("බැරොක් යුගයේ චිත්‍ර කලාවේ 'ට්‍රොම්ප් ලොයිල්' (Trompe-l'oeil - ඇස රැවටීම) හා සිවිලිම් සිතුවම්වලින් අපේක්ෂා කළේ කුමක්ද?", "සිවිලිම ස්වර්ගයට විවෘත වූවාක් මෙන් දෘෂ්ටි මායාව මැවීම", "බිත්තිවල ඇති සියලු ජනෙල් කළු තීන්තෙන් වැසීම", "රූප සියල්ල පැතලි ද්විමාන ලෙස කුඩා කර පෙන්වීම", "වියුක්ත රේඛා රටා මගින් කැන්වසය බෙදා දැක්වීම", "ෆ්‍රෙස්කෝ සිතුවම් හා ස්ටක්කෝ මූර්ති මුසු කර බලන්නාගේ ඇස ස්වර්ගීය අවකාශයකට ගෙන යාම බැරොක් ක්‍රමයයි."),
        q("පුනරුද චිත්‍ර ශිල්පී 'පියෙරෝ ඩෙලා ෆ්‍රැන්චෙස්කා' (Piero della Francesca) ගේ සිතුවම්වල ඇති ප්‍රධාන ගුණාංගය කුමක්ද?", "ගණිතමය නිශ්චල සමබරතාව හා පැහැදිලි ආලෝකය", "වේගවත් නොසන්සුන් පින්සල් පහරවල් හා අඳුර", "බොඳ වූ කළු පැහැති කඳු පසුබිම හා භීතිය", "තීන්ත කැන්වසය මත ඉසින ලද අහඹු රටාව", "ගණිතඥයෙකුද වූ ඔහුගේ සිතුවම්වල ජ්‍යාමිතික ආකෘති හා සාමකාමී සංයමය මැනවින් දිස්වේ."),
        q("උතුරු පුනරුදයේ නෙදර්ලන්ත ශිල්පී 'පීටර් බෲගල්' (Pieter Bruegel) ඇඳි 'හිම මත දඩයක්කාරයෝ' සිතුවම විශේෂ වන්නේ ඇයි?", "පරිසරයේ සීතල ඍතුව හා ගැමි ජීවිතය මුල් කිරීම නිසා", "රජුගේ මාලිගාවේ රන් ආභරණ විස්තර කිරීම නිසා", "හිම මත පැතලි රතු ඉරි පමණක් ඇඳ ඇති නිසා", "අන්ධ සමෝච්ඡ ක්‍රමයෙන් පැන්සලෙන් ඇඳ ඇති නිසා", "ගසේ සිට පහළ ගම්මානය දෙසට යන විකර්ණ චලනය හා සීතල පරිසරය ඔහු අපූරුවට සංයුති කළේය."),
        q("මධ්‍යකාලීන රෝමනෙස්ක් (Romanesque) දෙව්මැදුරු හා ගොතික් දෙව්මැදුරු වෙන් කරන ප්‍රධාන ආරුක්කු හැඩ වෙනස කුමක්ද?", "රෝමනෙස්ක් අර්ධ වෘත්තාකාර අතර ගොතික් උල් ආරුක්කුය", "රෝමනෙස්ක් උල් අතර ගොතික් පැතලි කොටු හැඩය", "රෝමනෙස්ක් වීදුරු අතර ගොතික් ලී කණු පමණි", "දෙකෙහිම කිසිදු ආරුක්කු හැඩයක් භාවිත නොකරයි", "රෝමනෙස්ක් දෙව්මැදුරු ඝන බිත්ති හා අඳුරු ඇතුළතක් ගත් අතර ගොතික් උසට හා ආලෝකයට ඉඩ දුන්නේය."),
        q("ගොතික් ආසන දෙව්මැදුරුවල ප්‍රධාන පිවිසුම් දොරටුව ඉහළින් ඇති අර්ධ වෘත්තාකාර කැටයම් පුවරුව හඳුන්වන්නේ කුමන නමින්ද?", "ටිම්පනම් (Tympanum)", "සඳකඩපහණ (Moonstone)", "පෙඩිමන්ට් (Pediment)", "මෙටොප් (Metope)", "අවසන් විනිශ්චය වැනි කතා පුවත් දෙවොලට ඇතුළු වන බැතිමතුන්ට පෙනෙන සේ ටිම්පනම් තුළ කැටයම් කර ඇත."),
        q("17 වන සියවසේ ප්‍රංශ සම්භාව්‍ය බැරොක් ශිල්පී 'නිකොලස් පුසාන්' (Nicolas Poussin) ප්‍රමුඛත්වය දුන් භූ දර්ශන සිතුවම් රීතිය කුමක්ද?", "විනයගරුක ජ්‍යාමිතික සංයුතිය හා සම්භාව්‍ය සංයමය", "වේගවත් හැඟීම්බර අවුල් සහගත වර්ණ පහර", "කැඩුණු වීදුරු කැබලි මොසැයික් නිර්මාණ", "සාමාන්‍ය කම්කරුවන්ගේ රළු දෛනික රූප", "පැහැදිලි ආලෝකය හා පුරාණ ග්‍රීක-රෝම වාස්තු සැලසුම් ඇති ඔහුගේ ශෛලිය ප්‍රංශ ඇකඩමියේ පදනම විය."),
        q("රෝමයේ 'නෙරෝගේ රන් මාලිගයේ' (Domus Aurea) කැණීම්වලින් පුනරුද ශිල්පීන් හඳුනාගත් සැරසිලි බිතුසිතුවම් ක්‍රමය කුමක්ද?", "ග්‍රෝටෙස්ක් (Grotesque) මෝස්තර හා පොම්පේයි ශෛලිය", "චීන සෝං රාජවංශ තීන්ත සේදුම් ක්‍රමය", "ජපන් උකියෝ-එ ලී අච්චු මුද්‍රණ ක්‍රමය", "ඉන්දියානු රාජ්පුත් ක්ෂුද්‍ර සිතුවම් ක්‍රමය", "පැරණි රෝම බිත්ති සැරසිලිවල ලියවැල් හා කල්පිත රූප රෆායෙල් ඇතුළු පුනරුද ශිල්පීන්ට මහත් ආභාසයක් විය."),
        q("ප්‍රංශ ජාතික මූර්ති ශිල්පී 'ඕගස්ට් රොඩෑන්' (Auguste Rodin) බටහිර සම්භාව්‍ය සම්ප්‍රදායෙන් නූතන මූර්ති කලාවට පිවිසුණේ කුමන කෘතියෙන්ද?", "සිතන්නා (The Thinker) සහ නිරයේ දොරටු", "සාරානාත් හිඳි බුදු පිළිමය (Sarnath Buddha)", "මිලෝ හි වීනස් (Venus de Milo)", "ඩොරිෆොරොස් හෙවත් හෙල්ල දරන්නා", "ඔප දැමූ සිනිඳු බව වෙනුවට ආලෝකය හා සෙවණැලි ග්‍රහණය වන රළු මැටි හා ලෝකඩ මතුපිට ඔහු භාවිත කළේය."),
        q("ලියනාඩෝ ඩා වින්චිගේ සිතුවම් ගණනාවක්ම අසම්පූර්ණව පැවතීමට හෝ විනාශ වීමට ප්‍රධාන හේතුව කුමක්ද?", "නව තීන්ත මාධ්‍ය අත්හදා බැලීම හා බහුවිධ කුතුහලය", "ඔහුට කිසිදු වර්ණ මිශ්‍රණ දැනුමක් නොතිබීම", "පුනරුද රජවරුන් ඔහුගේ සිතුවම් පිළිස්සීම", "ඔහු දියසායම් වලින් පමණක් කඩදාසියේ ඇඳීම", "අවසන් රාත්‍රී භෝජනයේදී තෙත් බදාම වෙනුවට වියළි බිත්තියේ තෙල්-ටෙම්පරා අත්හදා බැලීමෙන් තීන්ත ගැලවිණි."),
        q("පුනරුද කලාකරුවෙකු සැබෑ ලෙසම විද්‍යාඥයෙකු වූ බව පෙන්වන 'ඩා වින්චිගේ ව්‍යුහ විද්‍යාත්මක සටහන්' තුළ ඔහු කළේ කුමක්ද?", "මානව අස්ථි හා මාංශ පේශි නිරීක්ෂණය කර ඇඳීම", "කෘත්‍රිම ප්ලාස්ටික් ශරීර ආකෘති වෙළඳාම් කිරීම", "ග්‍රීක පිළිමවල පිටපත් පමණක් බලා ඇඳීම", "සියලුම සිරුරු වියුක්ත ත්‍රිකෝණවලට හැරවීම", "සිරුරේ ඇතුළත පිහිටීම නිවැරදිව වටහා ගැනීම නිසා පුනරුද සිතුවම්වල ජීවී ඉරියව් අතිශය ස්වාභාවික විය."),
        q("බැරොක් කලාවේදී 'ගතික සංයුතිය' (Dynamic Composition) මැවීම සඳහා ශිල්පීන් බහුලව භාවිත කළ ජ්‍යාමිතික රේඛාව කුමක්ද?", "විකර්ණ රේඛාව හා ප්‍රතිවිරුද්ධ ආලෝකය", "සමාන්තර තිරස් රේඛාව හා පැතලි වර්ණය", "නොසැලෙන සිරස් අක්ෂය හා සමමිතිය", "කුඩා තිරස් කොටු දැල් රටාව", "පුනරුදයේ තිරස්-සිරස් සමබරතාව බිඳ දමමින් ඇල වූ විකර්ණ රේඛා මගින් බැරොක් ශිල්පීන් චලනය ඉස්මතු කළහ."),
        q("පැරණි ග්‍රීසියේ සිට රොකෝකෝ හා නව-සම්භාව්‍යවාදය දක්වා බටහිර කලාවේ මූලික ගමන් මග හඳුනා ගත හැකි පොදු ලක්ෂණය කුමක්ද?", "සම්භාව්‍ය යථාර්ථය හා සංවේදී හැඟීම් අතර මාරු වීම", "සෑම යුගයකම එකම මිසර නීතිය නොවෙනස්ව පැවතීම", "වර්ණ භාවිතය සම්පූර්ණයෙන් අත්හැරීම", "කිසිදු ත්‍රිමාණ ගැඹුරක් නොදැක්වීම", "සමමිතික සම්භාව්‍ය පිළිවෙළ (ග්‍රීක/පුනරුද/නව-සම්භාව්‍ය) හා භාවාත්මක චලනය (හෙලනිස්තික/බැරොක්/රොමෑන්තික) මාරුවෙන් මාරුවට පැමිණියේය."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ සිසුවෙකුට 'බටහිර සම්භාව්‍ය කලාව' හැදෑරීමෙන් ලැබෙන ප්‍රායෝගික අවබෝධය කුමක්ද?", "දෘෂ්ටිකෝණ, එළිය-අඳුර හා සිරුරු අනුපාත වටහා ගැනීම", "බතික් ඉටි රටා හා ලාක්ෂා කර්මාන්තය පුහුණු වීම", "සිංහල පුස්කොළ පොත් ලේඛන කලාව ප්‍රගුණ කිරීම", "සෙරමික් දුම් ගැස්වීමේ ක්‍රමවේද ඉගෙන ගැනීම", "පුනරුද රේඛීය දෘෂ්ටිකෝණය හා බැරොක් චියරොස්කුරෝ තානය සිසුන්ගේ නිශ්චල ජීව චිත්‍රවලට සෘජුවම උපකාරී වේ.")
    )
}
